import React, { useState, useRef, useEffect, use } from "react";
import { DateRange } from "react-date-range";
import { enUS } from "date-fns/locale";
import { Button, Card, Modal } from "react-bootstrap";
import { toast, ToastContainer } from "react-toastify";
import DataTable from "react-data-table-component";
import { FaCalendarAlt, FaPen } from "react-icons/fa";
import { LazyLoadImage } from "react-lazy-load-image-component";
import { AiOutlineSend } from "react-icons/ai";
import { RiAttachment2 } from "react-icons/ri";
import { Spinner } from "react-bootstrap";
import { MdRefresh } from "react-icons/md";
import { makeApiRequest } from "../../axiosService/ApiCall";
import io from "socket.io-client";
import config from "../../axiosService/Config";
import { encryptData, decryptData } from "../../Auth/SecurityCrypto";
import Papa from "papaparse";
import { saveAs } from "file-saver";
import axios from "axios";

function SupportTicketHistory() {
    const [socketConnection, setSocket] = useState(null);
    const [allTicket, setAllTicket] = useState([]);
    const [loading, setLoading] = useState(true);
    const [issueList, setIssueList] = useState([]);
    const [search, setSearch] = useState("");
    const [currentPage, setCurrentPage] = useState(1);
    const [type, setType] = useState("All");
    const [limit, setLimit] = useState(10);
    const [status, setStatus] = useState("");
    const [fromDate, setFromDate] = useState("");
    const [toDate, setToDate] = useState("");
    const [showCalendar, setShowCalendar] = useState(false);
    const [totalItems, setTotalItems] = useState(0);
    const [isRefreshing, setIsRefreshing] = useState(false);
    const [is_Refreshing, setIs_Refreshing] = useState(false);
    const [resetPaginationToggle, setResetPaginationToggle] = useState(false);
    const [selectedTicket, setSelectedTicket] = useState(null);
    const [adminMessage, setAdminMessage] = useState("");
    const [fileName, setFileName] = useState("");
    const [chatAttachment, setChatAttachment] = useState(null);
    const [sending, setSending] = useState(false);
    const [chattingHistory, setchattingHistory] = useState([]);
    const [ticketId, setTicketId] = useState("");
    const [editDataSupport, setEditDataSupport] = useState(null);
    const [adminType, setAdminType] = useState("");


    const fileInputRef = useRef(null);

    useEffect(() => {
        getIssue();
        getAllTickets(currentPage);
    }, []);

    useEffect(() => {
        getAllTickets(currentPage);
    }, [type, search, status, fromDate, toDate, currentPage, limit]);

    useEffect(() => {
        const newSocket = io(config.backendurl, {
            transports: ["websocket"],
            debug: false,
        });

        setSocket(newSocket);

        newSocket.on("connect", () => {
            console.log("Socket connected:");
        });

        newSocket.on("connect_error", (err) => {
            console.error("Socket connection error:", err);
        });

        return () => newSocket.disconnect();
    }, []);

    useEffect(() => {
        if (socketConnection != null) {
            socketConnection.on("chattingTicketResponse", (data) => {
                // if (selectedTicket._id != data.ticketId) return
                if (String(selectedTicket?._id) !== String(data.ticketId)) return;


                if (data && data.userHistory) {
                    const chatHis = data.userHistory;
                    if (chatHis && chatHis.length > 0) {
                        const resulData = chatHis.find(
                            (hisData) => hisData.ticketId == ticketId
                        );
                        if (resulData && resulData.chatHistory) {
                            setchattingHistory(resulData.chatHistory);
                            setSelectedTicket((prevTicket) => {
                                if (prevTicket && prevTicket.ticketId === ticketId) {
                                    return { ...prevTicket, chatHistory: resulData.chatHistory };
                                }
                                return prevTicket;
                            });
                        } else {
                            if (ticketId == data.ticketId) {
                                chattingHistory.push(data.chatHistory);
                            }
                        }
                    }
                }
            });
        }
    }, [socketConnection, ticketId]);

    const [showModal, setShowModal] = useState(false);
    const handleClose = () => {
        setShowModal(false);
        setTicketId("");
        setAdminMessage("");
        setchattingHistory([]);
    };

    const [range, setRange] = useState([
        {
            startDate: new Date(),
            endDate: new Date(),
            key: "selection",
        },
    ]);
    const calendarRef = useRef(null);

    const handleReset = async () => {
        setLimit(10);
        setCurrentPage(1);
