        const acceptType = ["jpg", "jpeg", "png"];
        if (file.size > 1024 * 1024) {
            toast.error("File size must be less than 1 MB");
            resetFile();
            return;
        }
        if (!acceptType.includes(ext)) {
            toast.error("Invalid file format. Only JPG, JPEG, and PNG allowed.");
            resetFile();
            return;
        }

        setChatAttachment(file);
        setFileName(file.name);
