    const handleSendMessage = async (id) => {
        if (editDataSupport == 0 && adminType == "SubAdmin") {
            toast.warning("You dont have permission to edit this page");
            return;
        }
        if (!adminMessage.trim() && !chatAttachment) {
            toast.error("Message or Attachment is required");
            return;
        }
        try {
            let uploadFile = chatAttachment;

            setSending(true);
            if (uploadFile == null || uploadFile == "") {
                const encryptedPayload = encryptData({
                    ticketId: id,
                    ticketChat: adminMessage,
                    attachment: "",
                });
                const params = {
                    url: `reply`,
                    method: "POST",
                    data: { encryptedData: encryptedPayload },
                };
                const result = await makeApiRequest(params);
                if (result.encryptedData) {
                    const decryptedResponse = decryptData(result.encryptedData);
                    if (decryptedResponse.status) {
                        const chatHis = decryptedResponse.history;
                        if (Array.isArray(chatHis)) {
                            const resulData = chatHis.find(
                                (hisData) => hisData.ticketId == ticketId
                            );
                            setchattingHistory(resulData.chatHistory);
                        }
                        setSending(false);
                        setChatAttachment("");
                        setAdminMessage("");
                        viewTickets(id);
                        setFileName("");
                    }
                }
            } else {
                const formData = new FormData();
                let sizeFile = 1;
                let fileToUpload = uploadFile;
                let fileName = "attachment";
                let fileExtension = fileToUpload.name.split("?")[0].split(".").pop();
                formData.append(
                    "images[]",
                    fileToUpload,
                    fileName + "." + fileExtension
                );
                const params = {
                    url: `fileUpload?sizeFile=${sizeFile}&&type="attachment"`,
                    method: "POST",
                    data: formData,
                    header: "image",
                };
                //Start Load
                setSending(true);
                const response = await makeApiRequest(params);
                // Stop Loader
                if (response.status) {
                    const encryptedPayload = encryptData({
                        ticketId: id,
                        ticketChat: adminMessage,
                        attachment: response.message[0].name,
                    });
                    const reqData = {
                        url: `reply`,
                        method: "POST",
                        data: { encryptedData: encryptedPayload },
                    };
                    const result = await makeApiRequest(reqData);
                    if (result.encryptedData) {
                        const decryptedResponse = decryptData(result.encryptedData);
                        if (decryptedResponse.status) {
                            const chatHis = decryptedResponse.history;
                            if (Array.isArray(chatHis)) {
                                const resulData = chatHis.find(
                                    (hisData) => hisData.ticketId == ticketId
                                );
                                setchattingHistory(resulData.chatHistory);
                            }

                            setSending(false);
                            setChatAttachment("");
                            setAdminMessage("");
                            viewTickets(id);
                            setFileName("");
                        }
                    }
                }
            }
        } catch (error) {
            console.log("error---", error);
        } finally {
            setSending(false);
        }
    };

