                                    value={adminMessage}
                                    onChange={(e) => setAdminMessage(e.target.value)}
                                    disabled={sending || (editDataSupport == 0 && adminType == "SubAdmin")}
                                // disabled={editDataSupport == 0 && adminType == "SubAdmin"}
                                />
                                <button
                                    type="submit"
                                    className="input-group-text"
                                    disabled={sending}
                                >
                                    {sending ? (
                                        <Spinner animation="border" size="sm" />
                                    ) : (
                                        <AiOutlineSend />
                                    )}
                                </button>

                                <button
                                    type="button"
                                    className="input-group-text"
                                    onClick={() => fileInputRef.current.click()}
                                >
                                    <RiAttachment2 />
                                </button>
                            </div>
                            <input
                                type="file"
                                ref={fileInputRef}
                                hidden
                                accept="image/*"
                                onChange={handleFileSelect}
                                disabled={selectedTicket?.status == 0 ? true : false ||
                                    editDataSupport == 0 && adminType == "SubAdmin"}
                            />
                        </form>
                    </div>

                    <div className="d-flex flex-row justify-content-end gap-3">
                        <Button
                            variant={
                                selectedTicket?.status === 1
                                    ? "outline-danger"
                                    : "outline-success"
                            }
                            className="px-4"
                            onClick={handleCloseTicket}
                            disabled={editDataSupport == 0 && adminType == "SubAdmin"}
                        >
                            {selectedTicket?.status === 1 ? "Close Ticket" : "Reopen Ticket"}
                        </Button>
                        <Button
                            className="custom-nav-button-1 active py-2"
                            onClick={() => {
                                resetMessageForm();
                                handleClose();
                            }}
                        >
                            Cancel
                        </Button>
                    </div>
                </Modal.Footer>
            </Modal>
        </>
    );
}

export default SupportTicketHistory;
